#!/bin/sh
# Create the `automerge` path dependency the oracle crate compiles against.
#
# The oracle is a Cargo crate which depends on the upstream Rust implementation
# by path. That path is a machine specific location, so it is wired up
# with symlinks generated by this script rather than committed. They point into
# a read only checkout which is never modified.
#
# The checkout is found in one of two places, tried in this order:
#
#   1. $AUTOMERGE_REF, when it is set *and* names an automerge checkout.
#   2. The checkout beside this repository, `../github-automerge-automerge`.
#      Resolved from this script's own location, never from the caller's
#      working directory: a build step that resolves a path against whatever
#      directory the user happened to be in is a step that works on one machine
#      and fails on the next.
#
# There is no third place, and no compiled in absolute path: this script is
# committed, so a location that holds on one machine and not on the next is a
# defect that hides as a build error. When neither candidate is a checkout the
# script stops and names both of them, with the reason each was refused, so the
# failure says what to fix rather than that something is wrong.
#
# The script is idempotent, and it checks every target before writing anything,
# so a bad environment never leaves a half linked vendor tree behind.
#
# POSIX sh, because the build runner invokes it as `sh tools/link-oracle.sh`.

set -eu

# Directory holding this script, so the vendor tree is found no matter what the
# working directory is.
script_dir=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)

vendor_dir="$script_dir/oracle/vendor"

# The cargo workspace inside the reference checkout, relative to its root.
crate_relpath="rust"

# The crates which must be visible in `vendor/`. `automerge` is the reference
# implementation itself. Cargo resolves the path dependencies of a path
# dependency relative to the symlink path rather than the symlink target, so
# the rest of the closure the manifests reach has to be linked in too:
# `automerge` depends on `hexane` and on `automerge-test` as a dev dependency,
# and `automerge-test` depends back on `automerge`.
crates="automerge hexane automerge-test"

# The checkout beside this repository. `script_dir` is the `tools/` directory,
# so the repository root is its parent and the sibling is that parent's
# sibling. `dirname` is handed an absolute path, so the result never depends on
# where the caller was standing.
repo_root=$(CDPATH='' cd -- "$script_dir/.." && pwd)
sibling_ref=$(dirname -- "$repo_root")/github-automerge-automerge

# The checkout to link against, and the reason each candidate was refused, so a
# total failure can report all of it rather than the last thing that went wrong.
ref=''
refused=''

# Record why a candidate is unusable, as one reportable entry: the label naming
# where the candidate came from, the path, and the reason.
refuse() {
    refused="$refused  $1: $2
      $3
"
}

# Accept the candidate named by $2, labelled $1, when it is an automerge
# checkout, and say why it is not when it is not. A candidate counts as a
# checkout when it is a directory holding every crate the oracle's manifests
# resolve by path; a directory that exists but is something else is a wrong
# answer, not a usable one, so it does not win over a candidate that works.
try_ref() {
    if [ ! -d "$2" ]; then
        refuse "$1" "$2" 'it is not a directory'
        return
    fi
    for crate in $crates; do
        if [ ! -d "$2/$crate_relpath/$crate" ]; then
            refuse "$1" "$2" "it has no $crate_relpath/$crate, so it is not an automerge checkout"
            return
        fi
    done
    ref="$2"
}

if [ -n "${AUTOMERGE_REF:-}" ]; then
    try_ref 'AUTOMERGE_REF' "$AUTOMERGE_REF"
fi

if [ -z "$ref" ]; then
    if [ -z "${AUTOMERGE_REF:-}" ]; then
        refuse 'AUTOMERGE_REF' '(unset)' 'the variable is not set'
    fi
    try_ref 'the sibling checkout' "$sibling_ref"
fi

if [ -z "$ref" ]; then
    {
        echo "link-oracle.sh: no automerge checkout to link the oracle against."
        echo "link-oracle.sh: tried, in order:"
        printf '%s' "$refused"
        echo "link-oracle.sh: set AUTOMERGE_REF to an automerge checkout, or put one"
        echo "link-oracle.sh: beside this repository as github-automerge-automerge."
    } >&2
    exit 1
fi

# A fallback is a decision the reader has to be able to see: the vectors this
# build then produces come from a different checkout than the environment asked
# for, and a conformance gate is exactly the place where that must not be
# silent.
if [ -n "${AUTOMERGE_REF:-}" ] && [ "$ref" != "$AUTOMERGE_REF" ]; then
    echo "link-oracle.sh: AUTOMERGE_REF=$AUTOMERGE_REF is not an automerge checkout;" >&2
    echo "link-oracle.sh: using $ref instead" >&2
fi

mkdir -p "$vendor_dir"

for crate in $crates; do
    link_path="$vendor_dir/$crate"
    target="$ref/$crate_relpath/$crate"
    # Already pointing at the right place: nothing to do.
    if [ -L "$link_path" ] && [ "$(readlink "$link_path")" = "$target" ]; then
        continue
    fi
    # Either a symlink to somewhere else or a real checkout. Both are replaced.
    rm -rf "$link_path"
    ln -s "$target" "$link_path"
done
